import {cleanAppearance,giftScenes} from './appearance.js';
export function createPresentation3D(THREE,scene,canvas,initial,onChange){
 let design=cleanAppearance(initial),start=0,from=0,to=0,running=false,orbitX=0,orbitY=0,drag=null,ended=false,lastPose=null;
 const particles=new THREE.Group();scene.add(particles);const shapes=[new THREE.BoxGeometry(.045,.085,.018),new THREE.TetrahedronGeometry(.04),new THREE.SphereGeometry(.027,8,6)];for(let i=0;i<18;i++){const material=new THREE.MeshStandardMaterial({color:['#dd7054','#e9ba61','#7c9fb8','#b787a1'][i%4],roughness:.75});const mesh=new THREE.Mesh(shapes[i%3],material);mesh.visible=false;particles.add(mesh);}
 const shadowCanvas=document.createElement('canvas');shadowCanvas.width=256;shadowCanvas.height=256;const ctx=shadowCanvas.getContext('2d'),gradient=ctx.createRadialGradient(128,128,2,128,128,120);gradient.addColorStop(0,'rgba(37,25,18,.20)');gradient.addColorStop(1,'rgba(37,25,18,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,256,256);const shadow=new THREE.Mesh(new THREE.PlaneGeometry(1,1),new THREE.MeshBasicMaterial({map:new THREE.CanvasTexture(shadowCanvas),transparent:true,depthWrite:false}));shadow.position.z=-.5;scene.add(shadow);
 function update(value){design=cleanAppearance(value);scene.background=new THREE.Color(giftScenes[design.scene].color);onChange();}
 function begin(open,current=0){from=current;to=open?1:0;start=performance.now();running=true;onChange();}
 function pose(time,paused,width,height){const none=paused||design.animation==='none',duration={classic:1000,gentle:1500,spin:1650,float:1250,pop:1150,confetti:1450,none:0}[design.animation],p=none?1:running?Math.max(0,Math.min(1,(time-start)/duration)):1,ease=design.animation==='classic'?p*p*(3-2*p):1-(1-p)**3;let opening=from+(to-from)*ease;if(design.animation==='spin'&&to===1&&running)opening=Math.max(0,(ease-.3)/.7);if(p>=1)running=false;const lively=design.animation==='float'&&to===1&&!none,bob=lively?Math.sin(time/1500)*.028:design.animation==='gentle'&&p<1?-.12*(1-ease):0,spin=design.animation==='spin'&&to===1&&p<1?(1-ease)*Math.PI*2:0,pop=design.animation==='pop'&&to===1&&p<1?.9+.1*ease+.045*Math.sin(p*Math.PI):1;
  const celebration=design.animation==='confetti'&&to===1&&!none&&(time-start)<duration+900&&(time-start)>350;particles.visible=celebration;if(celebration)particles.children.forEach((mesh,i)=>{const fall=((time-start-350)/1900+i*.037)%1,side=i%2?1:-1;mesh.visible=true;mesh.position.set(side*(width*(1+opening)*.53+.12+Math.sin(time/600+i)*.06),height*.7-fall*height*1.5,.18+Math.cos(i)*.1);mesh.rotation.set(time/650+i,time/900+i,i+time/1000);});
  shadow.scale.set(width*(1+opening)*.83,.34,1);shadow.position.y=-height*.5-.12;
  lastPose={opening:Math.max(0,Math.min(1,opening)),rotationX:-.08+orbitX+(lively?Math.sin(time/1700)*.008:0),rotationY:-.18+opening*.11+orbitY+spin,rotationZ:-.07+opening*.07+(lively?Math.sin(time/2200)*.009:0),bob,scale:pop,active:running||lively||celebration,animation:design.animation,scene:design.scene};return lastPose;
 }
 function down(event){if(event.button!==0)return;drag={x:event.clientX,y:event.clientY,orbitX,orbitY};canvas.setPointerCapture?.(event.pointerId);}
 function move(event){if(!drag)return;orbitY=drag.orbitY+(event.clientX-drag.x)*.008;orbitX=Math.max(-.3,Math.min(.3,drag.orbitX+(event.clientY-drag.y)*.005));onChange();}
 function up(){drag=null;}function key(event){const change={ArrowLeft:[-.13,0],ArrowRight:[.13,0],ArrowUp:[0,-.07],ArrowDown:[0,.07]}[event.key];if(!change)return;event.preventDefault();orbitY+=change[0];orbitX=Math.max(-.3,Math.min(.3,orbitX+change[1]));onChange();}
 canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Presente em 3D. Arraste para girar ou use as setas do teclado.');canvas.style.touchAction='pan-y';canvas.style.borderRadius='16px';canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',up);canvas.addEventListener('keydown',key);update(initial);
 return {set:update,begin,pose,reset(){orbitX=orbitY=0;onChange();},snapshot:()=>({animation:design.animation,scene:design.scene,orbitX,orbitY,running,pose:lastPose}),destroy(){if(ended)return;ended=true;canvas.removeEventListener('pointerdown',down);canvas.removeEventListener('pointermove',move);canvas.removeEventListener('pointerup',up);canvas.removeEventListener('pointercancel',up);canvas.removeEventListener('keydown',key);shadow.material.map.dispose();}};
}
